-- DATOS DE PRUEBA: 10 PERSONAS FICTICIAS, SEPTIEMBRE 2026
-- ============================================================================
-- Ejecutar EXCLUSIVAMENTE sobre una base vacía de demostración, tras esquema y seed.
-- No envía correos ni marca planillas como pagadas. Cuentas y CUSPP son inventados.
-- Clave pública de prueba: Demo_JYP_2026!; nunca reutilizar en producción.
-- Activación explícita en psql: SET app.entorno_pruebas = 'SI';\i pruebas-demo/datosprueba.sql
-- Una segunda ejecución falla y revierte: no se sobrescriben personas existentes.
BEGIN;
DO $$ BEGIN
 IF current_setting('app.entorno_pruebas', true) IS DISTINCT FROM 'SI' THEN
 RAISE EXCEPTION 'Active app.entorno_pruebas=SI solo en una BD de demostración'; END IF;
 IF EXISTS (SELECT 1 FROM empleados) THEN RAISE EXCEPTION 'La demostración requiere una BD sin empleados'; END IF;

 SET app.entorno_pruebas = 'SI';
END $$;

-- 1. ORGANIZACIÓN DE PRUEBA. Los seeders operativos no crean áreas ni personas.

